const PICTO_CACHE = {};
function pictoHas(key) { return !!PICTO_SRC[key]; }
function pictoSVG(key, cls) {
  const src = PICTO_SRC[key];
  if (!src) return '';
  let inner = PICTO_CACHE[key];
  if (inner === undefined) {
    inner = src.split('|').map(seg => {
      const sp = seg.indexOf(' '), code = seg.slice(0, sp), d = seg.slice(sp + 1), f = code.split(','), k = f[0][0];
      if (k === 'F' || k === 'G') return `<path d="${d}" fill="${k === 'F' ? 'currentColor' : 'var(--picto-cut)'}"/>`;
      let a = `<path d="${d}" fill="none" stroke="${k === 'S' ? 'currentColor' : 'var(--picto-cut)'}" stroke-width="${f[0].slice(1)}"`;
      a += f.includes('b') ? ' stroke-linecap="butt"' : ' stroke-linecap="round"';
      a += f.includes('m') ? ' stroke-linejoin="miter"' : ' stroke-linejoin="round"';
      const da = f.find(x => x[0] === 'd'); if (da) a += ` stroke-dasharray="${da.slice(1).replace(/_/g, ' ')}"`;
      return a + '/>';
    }).join('');
    PICTO_CACHE[key] = inner;
  }
  return `<svg class="picto${cls ? ' ' + cls : ''}" viewBox="0 0 64 64" aria-hidden="true">${inner}</svg>`;
}
function pictoFill(root) {
  (root || document).querySelectorAll('[data-picto]').forEach(el => { const k = el.dataset.picto; if (el.dataset.pictoOn !== k) { el.innerHTML = pictoSVG(k); el.dataset.pictoOn = k; } });
}
if (typeof document !== 'undefined') { if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => pictoFill()); else pictoFill(); }
